from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable


class OptionsInterface21B(object):
    def get_bts_rad_parameters(self, parameters_type, timeout=120):
        """
        Get RAD parameters.

        :param string parameters_type: Requested (SW Config, present in file) or Applied (SW Config +
            changes made during runtime)
        :param int timeout: Time to wait for positive procedure result.
        :return list: List of dicts containing flag:value pairs.

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getRadParameters.html
        """
        result = self._api_client.execute_infomodel_request("getRadParameters", {"type": parameters_type}, timeout)
        return result[0]["flags"]

    def check_link_status(self, timeout=60, detailed_output=False):
        """
        Check link status.

        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return Union[list,dict]: Active Session List feedback info or whole dict response if detailed_output is set
                                 to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getActiveSessionList.html
        """

        response = self._api_client.execute_customer_procedure(
            name='getActiveSessionList',
            parameters={},
            timeout=timeout)
        if response is None:
            raise DataNotAvailable("GetActiveSessionList data has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)
